// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The admin is the deployer (msg.sender in constructor)
        bool success;
        // Low-level call to capture return value without revert
        (success, ) = address(c).call(abi.encodeCall(c.setOwner, address(0x1234567890123456789012345678901234567890)));
        // success is true if the outer call didn't revert, but we need the actual return value
        // Use assembly to extract it
        bool setOwnerReturn;
        assembly {
            // success is true, returndatasize() is 32 bytes for one bool
            returndatacopy(0, 0, returndatasize())
            setOwnerReturn := mload(0)
        }
        assertTrue(setOwnerReturn == true); // reference returns true, mutant returns false
    }
}

