contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x1);
        // Call setOwner through the admin (the deployer, which is this test contract)
        vm.prank(address(this));
        c.setOwner(newOwner);
        // Assert that owner has been updated to newOwner
        // The reference contract will have owner == newOwner; the buggy one will have owner == address(this) (the deployer)
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Concrete scenario: non-admin calls setOwner
        address nonAdmin = address(0x1234);
        address newOwner = address(0x5678);

        // Check initial owner (the deployer, which is this contract)
        address initialOwner = c.owner();

        // Attempt to call setOwner as nonAdmin
        vm.prank(nonAdmin);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // In the reference (correct) contract, the call reverts because onlyAdmin modifier prevents it.
        // In the buggy version (require changed to require(msg.sender != admin)), the call succeeds and owner is changed.
        // Expect that the reference contract reverts, so success is false and owner remains initialOwner.
        assertTrue(!success && c.owner() == initialOwner, "Reference: revert and owner unchanged; bug: success and owner changed");
    }
}
